-- DB: qnfo-audit
-- Rollback: UPDATE reach_channel_profiles SET status = 'withdrawn', updated_at = datetime('now') WHERE channel IN ('linkedin','github','x','bluesky','mastodon') AND status = 'draft'; (the earlier AUTONOMY-PIVOT-1 drafts are in migrations/2026-11-09-autonomy-pivot.sql)
-- spof-review: no new cron, trigger, binding, host or credential in this file; draft text nothing posts from, one audience-matrix message, one decision_log row.
-- SYSTEMS-RESEARCHER-ARC-1 (2026-11-09, charter pillar reach; owner directive 2026-11-09): "update all surfaces ... positioning me based on my legitimate experience as a systems researcher, specifically
-- autonomous systems ... network modeling as early in my career through transportation and machine learning and now AI research". The arc is the verified record in jobsearch/facts.json and the bank
-- (DVRPC 2005-2008 systems planner, IBI Group 2008-2011, FHWA national tour-based model 2011-2015, Deloitte analytics and machine learning, Advisory Board senior data scientist 2016, QNFO 2024-).
-- Text stays status draft: first-person claims on the owner accounts are posted by the owner.
-- CAUSE-MAPPED: registers no metric.
UPDATE reach_channel_profiles SET status = 'draft', updated_at = datetime('now'), text = 'Systems researcher in autonomous AI systems | From transportation network models to machine learning to AI research | Founder, QNFO | FHWA, AARP' WHERE channel = 'linkedin' AND field = 'headline';
UPDATE reach_channel_profiles SET status = 'draft', updated_at = datetime('now'), text = 'Systems researcher: autonomous AI systems. Transport network models, then ML, now AI research. Ex-FHWA, AARP. Amsterdam. qnfo.org' WHERE channel = 'github' AND field = 'bio';
UPDATE reach_channel_profiles SET status = 'draft', updated_at = datetime('now'), text = 'Systems researcher on autonomous AI systems. Started with transport network models, then ML, now agents. Ex-FHWA, AARP. Amsterdam. qnfo.org' WHERE channel = 'x' AND field = 'bio';
UPDATE reach_channel_profiles SET status = 'draft', updated_at = datetime('now'), text = 'Systems researcher studying autonomous AI systems: how they operate, fail and get audited. Began with transport network models, then ML. Ex-FHWA, AARP. Posts drafted by my research pipeline are labelled. qnfo.org' WHERE channel = 'bluesky' AND field = 'bio';
UPDATE reach_channel_profiles SET status = 'draft', updated_at = datetime('now'), text = 'Systems researcher studying autonomous AI systems (QNFO): operation, failure modes, oversight and audit. I started with transportation network models (DVRPC, IBI Group, the FHWA national tour-based model), moved through analytics and machine learning, and now run an autonomous research system in the open with a public failure record. Interested in AI safety, agent reliability and the epistemics of AI-assisted research. Posts drafted by my research pipeline are labelled. #AI #AIsafety #agents #metascience' WHERE channel = 'mastodon' AND field = 'bio';
INSERT OR IGNORE INTO reach_channel_profiles (channel, field, text, max_chars) VALUES
 ('linkedin', 'about', 'I am a systems researcher. I started by building transportation network models (Delaware Valley Regional Planning Commission, IBI Group), led technical components of the national tour-based travel model at the Federal Highway Administration, and led AARP''s Livability Index. I moved through analytics and machine learning, and now study autonomous AI systems: how they operate, fail and get audited. I run an autonomous research system in the open at QNFO, with a public failure record. I am looking for collaborators and roles where understanding how complex systems behave when no one is steering is the work.', 2600);
UPDATE reach_channel_profiles SET status = 'draft', updated_at = datetime('now'), text = 'I am a systems researcher. I started by building transportation network models (Delaware Valley Regional Planning Commission, IBI Group), led technical components of the national tour-based travel model at the Federal Highway Administration, and led AARP''s Livability Index. I moved through analytics and machine learning, and now study autonomous AI systems: how they operate, fail and get audited. I run an autonomous research system in the open at QNFO, with a public failure record. I am looking for collaborators and roles where understanding how complex systems behave when no one is steering is the work.' WHERE channel = 'linkedin' AND field = 'about';
UPDATE reach_audience_matrix SET message = 'I am a systems researcher. I began with transportation network models, moved through analytics and machine learning, and now study autonomous AI systems: how they operate, fail and get audited. One case study a month with live numbers, including what failed.', updated_at = datetime('now') WHERE audience = 'employers-industry-leaders';
UPDATE reach_audience_matrix SET message = 'I study how autonomous AI systems operate, fail and get audited, and I run one in the open with a public failure record. My background is systems work: transportation network models, the FHWA national travel model, analytics and machine learning. I would like to compare notes and, if useful, work on a concrete problem together.', updated_at = datetime('now') WHERE audience = 'practitioners-autonomous-systems';
INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT
